function taskProgress(t){return t.status==='Done'?100:Array.isArray(t.checklist)&&t.checklist.length?Math.round(t.checklist.filter(c=>c.done).length/t.checklist.length*100):0;}
function projectProgress(p){const items=db.tasks.filter(t=>t.project===p.id);return items.length?Math.round(items.reduce((n,t)=>n+taskProgress(t),0)/items.length):(['Delivered','Portfolio Queue'].includes(p.status)?100:0);}
function normalizeWorkspace(){db.settings.accent=safeAccent(db.settings.accent);db.templates=Array.isArray(db.templates)?db.templates:[];db.tasks.forEach(t=>{t.checklist=Array.isArray(t.checklist)?t.checklist:[];t.progress=taskProgress(t)});db.projects.forEach(p=>p.progress=projectProgress(p));}
function avatar(name='Mineth',i=0){const u=db.users.find(u=>u.name===name||u.name.split(' ')[0]===name);return safeImage(u?.photo)?`<img class="avatar" src="${safeImage(u.photo)}" alt="${esc(name)}">`:legacyAvatar(name,i);}
function brandMark(invoiceMode=false){const src=safeImage(invoiceMode?(invoice?.logo||db.settings.invoiceLogo||db.settings.appLogo):db.settings.appLogo);return src?`<img class="brand-image ${invoiceMode?'invoice-brand':''}" src="${src}" alt="${esc(db.settings.brand)} logo">`:'<span class="logo">◕</span>';}
function setTheme(){window.studioMotionPreference=db.settings.motion||'System';const c=safeAccent(db.settings.accent);document.documentElement.style.setProperty('--orange',c);document.documentElement.style.setProperty('--accent',c);const rgb=c.slice(1).match(/../g).map(x=>parseInt(x,16));document.documentElement.style.setProperty('--accent-ink',(rgb[0]*.299+rgb[1]*.587+rgb[2]*.114)>150?'#101212':'#ffffff');}
function save(message){normalizeWorkspace();if(cloudMode){if(message){db.activity.unshift({text:message,date:new Date().toISOString()});db.activity=db.activity.slice(0,35)}cloudPending=true;cloudState=cloudConflict?'Conflict — changes not synced':'Saving…';updateCloudStatus();void flushCloud();}else{const current=localStorage.getItem(key);if(current!==localBaseline&&current!==JSON.stringify(db)){toast('Another tab changed this workspace. Export your changes before reloading.');return false}if(!localSave(message))return false;localBaseline=localStorage.getItem(key);}return true;}
async function flushCloud(){if(cloudBusy||cloudConflict||!cloudPending)return;cloudBusy=true;cloudPending=false;const snapshot=structuredClone(db);try{const {data,error}=await cloud.rpc('chakra_save',{payload:snapshot,expected_revision:cloudRevision});if(error)throw error;cloudRevision=Number(data);cloudState='Synced';}catch(e){cloudConflict=true;cloudPending=true;cloudState='Not synced — export or reload';toast(e.message);}finally{cloudBusy=false;updateCloudStatus();if(cloudPending&&!cloudConflict)void flushCloud();}}
function updateCloudStatus(){const el=$('#cloud-status');if(el)el.textContent=cloudState;}
function viewButtons(kind,current,values){return `<div class="view-switch" role="group" aria-label="${kind} view">${values.map(v=>`<button data-view="${kind}:${v}" aria-pressed="${current===v}" class="${current===v?'selected':''}">${v}</button>`).join('')}</div>`;}
function isMyTask(t){const profile=session?db.users.find(u=>u.email.toLowerCase()===session.user.email.toLowerCase()):null;const name=profile?.name||(!session?db.settings.owner:'');return t.assignee===session?.user?.email||!!name&&(t.assignee===name||t.assignee===name.split(' ')[0]);}
