tasks=function(){const html=originalTasks();const start=html.indexOf('<div class="kanban">');let list=db.tasks.filter(t=>(filter==='All'||filter==='Mine'&&isMyTask(t)||filter==='Overdue'&&t.due<today()&&t.status!=='Done'||filter==='Done'&&t.status==='Done')&&t.title.toLowerCase().includes(query.toLowerCase()));const controls=`<div class="view-toolbar">${viewButtons('tasks',taskView,['Board','List'])}<span class="section-note">Progress from completed checklist items</span></div>`;if(taskView==='Board')return html.slice(0,start)+controls+html.slice(start);return html.slice(0,start)+controls+`<div class="table-wrap"><table><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Due</th><th>Progress</th><th>Status</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td>${esc(t.title)} ${badge(t.priority)}</td><td>${esc(db.projects.find(p=>p.id===t.project)?.name||'Studio')}</td><td>${avatar(t.assignee)} ${esc(t.assignee)}</td><td>${date(t.due)}</td><td>${t.progress}% ${progress(t.progress)}</td><td><select data-task-status="${esc(t.id)}" aria-label="Status for ${esc(t.title)}">${options(['Backlog','In Progress','Review','Done'],t.status)}</select></td><td><button data-edit="tasks:${esc(t.id)}">Edit</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No matching tasks</div>'}</div>`;};
