function fxPanel(){return `<div class="fx-panel"><b>1 USD = ${Number(db.settings.fx).toFixed(2)} LKR</b><small>${fxBusy?'Refreshing…':fxError?esc(fxError):db.settings.fxUpdated?'Updated '+date(db.settings.fxUpdated):'Awaiting first live rate'}</small><button type="button" data-refresh-fx>Refresh rate</button><small>Refreshes once per 24 hours while open, or at the next launch. Last known rate is kept on failure.</small><a href="https://www.exchangerate-api.com" target="_blank" rel="noopener">Rates by ExchangeRate-API</a></div>`;}
async function refreshFX(force=false){if(fxBusy||(!force&&Date.now()-(db.settings.fxChecked||0)<86400000))return;fxBusy=true;try{const res=await fetch('https://open.er-api.com/v6/latest/USD',{signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('Rate service unavailable');const data=await res.json();if(data.result!=='success'||!Number.isFinite(data.rates?.LKR)||data.rates.LKR<=0)throw Error('Invalid exchange rate');db.settings.fx=data.rates.LKR;db.settings.fxUpdated=new Date(data.time_last_update_unix*1000).toISOString();db.settings.fxChecked=Date.now();fxError='';save();}catch(e){db.settings.fxChecked=Date.now();fxError='Live rate unavailable · using last saved rate';}finally{fxBusy=false;if(!$('#modal').open&&['settings','subscriptions'].includes(page))render();}}
function faviconMarkup(s){let host='';try{host=new URL(/^https?:\/\//.test(s.website)?s.website:'https://'+s.website).hostname}catch{}return `<span class="favicon-wrap"><span class="monogram">${esc(initials(s.name))}</span>${host?`<img class="favicon" src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=64" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}</span>`;}
