function extendRecord(kind,updated,form){if(kind==='tasks'){updated.checklist=Array.from(form.querySelectorAll('.checklist-edit-row')).map(row=>({id:row.dataset.checkId||id(),text:row.querySelector('[data-check-text]').value.trim(),done:row.querySelector('[data-check-done]').checked})).filter(c=>c.text);if(updated.status==='Done'&&db.tasks.find(t=>t.id===updated.id)?.status!=='Done')updated.checklist.forEach(c=>c.done=true);else if(updated.status==='Done'&&updated.checklist.some(c=>!c.done))updated.status='In Progress';else if(updated.checklist.length&&updated.checklist.every(c=>c.done))updated.status='Done';updated.progress=taskProgress(updated);}if(kind==='users'){updated.photo=form.dataset.photo||'';}if(kind==='projects')updated.progress=projectProgress(updated);}
edit=function(kind,recordId,status){originalEdit(kind,recordId,status);const form=$('#record-form'),x=db[kind]?.find(x=>x.id===recordId)||{};if(kind==='tasks'){const div=document.createElement('section');div.className='checklist-editor';div.innerHTML=`<div class="panel-head"><h3>Checklist</h3><button type="button" id="add-check">Add step</button></div><p class="section-note">Progress updates as steps are completed. With no checklist, mark the task Done to complete it.</p><div id="checklist-rows"></div>`;form.querySelector('.dialog-actions').before(div);const add=c=>{const row=document.createElement('div');row.className='checklist-edit-row';row.dataset.checkId=c.id||id();row.innerHTML=`<input type="checkbox" data-check-done aria-label="Step completed" ${c.done?'checked':''}><input data-check-text aria-label="Checklist step" value="${esc(c.text||'')}" placeholder="Describe a step"><button type="button" aria-label="Remove step">${icon('trash')}</button>`;row.querySelector('button').onclick=()=>row.remove();$('#checklist-rows').append(row);};(x.checklist||[]).forEach(add);$('#add-check').onclick=()=>add({});}if(kind==='projects'){const note=document.createElement('p');note.className='section-note';note.textContent='Progress is calculated from linked tasks. Projects with no tasks start at 0% unless delivered.';form.querySelector('.dialog-actions').before(note);}if(kind==='users'){form.dataset.photo=x.photo||'';const label=document.createElement('label');label.className='field';label.innerHTML=`Profile photo <input type="file" accept="image/png,image/jpeg,image/webp"><span id="photo-preview">${avatar(x.name||'Member')}</span>`;form.querySelector('.dialog-actions').before(label);label.querySelector('input').onchange=async e=>{try{const value=await imageData(e.target.files[0],256,180000);form.dataset.photo=value;$('#photo-preview').innerHTML=`<img class="avatar" src="${value}" alt="Profile preview">`;}catch(e){toast(e.message)}};}}
async function imageData(file,width=1600,maxBytes=800000){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPG or WebP image');if(file.size>10*1024*1024)throw Error('Image must be smaller than 10 MB');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,width/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const value=canvas.toDataURL('image/webp',.85);if(value.length>maxBytes)throw Error('Image is too detailed. Try a smaller file.');return value;}
clients=function(){let html=originalClients();const list=db.clients.filter(c=>(filter==='All'||c.status===filter)&&(!query||(c.name+c.contact+c.email).toLowerCase().includes(query.toLowerCase()))),c=list.find(x=>x.id===clientSelected)||list[0];if(c)html=html.replace('</dl>',`</dl><div class="portal-actions"><button data-portal-preview="${esc(c.id)}">Preview Portal</button><button data-portal-access="${esc(c.id)}">Portal Link & Access</button></div>`);return html;};
