async function grantAccess(email,role,client_id){if(!cloudMode||access?.role!=='owner'){toast('Sign in as owner and connect the cloud workspace first');return false}const {error}=await cloud.from('chakra_members').upsert({email:email.toLowerCase().trim(),role,client_id,active:true});if(error){toast(error.message);return false}toast('Access enabled. Share the sign-in link with this person.');void showAccessList();return true;}
