async function renderPortal(){let cid;try{cid=decodeURIComponent(page.slice(7))}catch{cid='invalid'}$('#app').innerHTML=`<main class="portal-shell"><header><h1>Client Portal</h1><button id="portal-account">${session?'Account':'Sign In'}</button></header><div id="portal-body">${session?'Loading your projects…':'Sign in with the email your studio enabled for this portal.'}</div></main>`;$('#portal-account').onclick=accountDialog;if(!session)return;let result;try{result=await cloud.rpc('chakra_portal',{requested_client:cid})}catch(e){if($('#portal-body'))$('#portal-body').textContent='Portal unavailable: '+e.message;return}const {data,error}=result;if(page!=='portal='+encodeURIComponent(cid)&&page!=='portal='+cid)return;if(error){$('#portal-body').textContent=error.message;return}portalData=data;document.documentElement.style.setProperty('--accent',safeAccent(data.settings.accent));$('#portal-body').innerHTML=(safeImage(data.settings.appLogo)?`<img class="brand-image" alt="Studio logo" src="${safeImage(data.settings.appLogo)}">`:'')+`<p>${esc(data.settings.studio)}</p>`+portalHTML(data);}
function accountDialog(){if(!cloud){toast('Cloud connection is unavailable. Your local workspace remains usable.');return}if(session){modal('Your Account',`<p>${esc(session.user.email)}</p><p class="section-note">${access?esc(access.role)+' access':'No workspace access enabled for this email.'} · ${esc(cloudState)}</p><div class="account-actions">${access&&access.role!=='client'?`<button id="load-cloud">Reload Cloud Workspace</button>${access.role==='owner'?'<button id="upload-cloud">Upload This Workspace</button>':''}<button id="export-unsynced">Export Current Data</button>`:''}<button id="sign-out">Sign Out</button></div>`);if($('#load-cloud'))$('#load-cloud').onclick=()=>confirmCloudLoad();if($('#upload-cloud'))$('#upload-cloud').onclick=()=>confirmCloudUpload();if($('#export-unsynced'))$('#export-unsynced').onclick=()=>action('export');$('#sign-out').onclick=async()=>{const {error}=await cloud.auth.signOut();if(error){toast(error.message);return}session=null;access=null;cloudMode=false;cloudConflict=false;cloudPending=false;db=JSON.parse(localStorage.getItem(key))||structuredClone(seed);$('#modal').close();render()};return;}modal('Sign In',`<form id="auth-form">${field('Email',input('email','','email',true,'autocomplete="email"'))}${field('Password',input('password','','password',true,'minlength="8" autocomplete="current-password"'))}<div class="dialog-actions"><button class="primary" name="mode" value="login">Sign In</button><button name="mode" value="signup">Create Account</button></div><p id="auth-message" role="status" class="section-note"></p></form><p class="section-note">Use your own email. Creating an account does not grant access until the studio owner enables it.</p>`);$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.target,v=Object.fromEntries(new FormData(form)),signup=e.submitter?.value==='signup';const msg=$('#auth-message');msg.textContent=signup?'Creating account…':'Signing in…';form.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=signup?await cloud.auth.signUp({email:v.email,password:v.password,options:{emailRedirectTo:APP_URL}}):await cloud.auth.signInWithPassword({email:v.email,password:v.password});if(result.error)throw result.error;if(!result.data.session){msg.textContent='Check your email to confirm your account, then sign in. If email delivery fails, the workspace owner needs to configure email delivery in Supabase.';return}session=result.data.session;await loadAccess();$('#modal').close();if(access?.role==='client'){page='portal='+access.client_id;render()}else if(access){await loadCloud(false);render();if(!cloudMode)accountDialog();}else{render();accountDialog()}}catch(err){msg.textContent=err.message;}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false)}};}
async function loadAccess(){const {data,error}=await cloud.from('chakra_members').select('*').eq('email',session.user.email.toLowerCase()).eq('active',true).maybeSingle();if(error)throw error;access=data;}
async function loadCloud(force){const {data,error}=await cloud.from('chakra_workspace').select('*').eq('id',true).single();if(error)throw error;cloudRevision=Number(data.revision);if(data.data){if(!validDB(data.data))throw Error('Cloud workspace has an invalid format');db=data.data;cloudMode=true;cloudConflict=false;cloudPending=false;cloudState='Synced';}else{cloudState='Cloud workspace is empty';cloudMode=false;}return !!data.data;}
function confirmCloudLoad(){modal('Reload cloud data?',`<p>Unsynced changes will be replaced. Export them first if needed.</p><button id="backup-cloud">Export Current Data</button><button id="confirm-cloud-load" class="primary">Reload Cloud</button>`);$('#backup-cloud').onclick=()=>action('export');$('#confirm-cloud-load').onclick=async()=>{try{await loadCloud(true);$('#modal').close();render()}catch(e){toast(e.message)}};}
function confirmCloudUpload(){modal('Upload this workspace?',`<p>Upload ${db.projects.length} projects, ${db.tasks.length} tasks and studio settings to the shared workspace. This replaces existing cloud records.</p><p class="section-note">Your current browser workspace remains available when signed out.</p><button id="confirm-cloud-upload" class="primary">Upload Workspace</button>`);$('#confirm-cloud-upload').onclick=async()=>{try{const {data,error}=await cloud.from('chakra_workspace').select('revision').eq('id',true).single();if(error)throw error;cloudRevision=Number(data.revision);normalizeWorkspace();const result=await cloud.rpc('chakra_save',{payload:structuredClone(db),expected_revision:cloudRevision});if(result.error)throw result.error;cloudRevision=Number(result.data);cloudMode=true;cloudConflict=false;cloudPending=false;cloudState='Synced';toast('Workspace uploaded');$('#modal').close();render()}catch(e){toast(e.message)}};}
// Initialize only after all overrides are installed.
async function bootStudio(){normalizeWorkspace();render();if(!window.createSupabaseClient){cloudState='Cloud unavailable';return}cloud=window.createSupabaseClient(CLOUD_URL,CLOUD_KEY);try{const {data,error}=await cloud.auth.getSession();if(error)throw error;session=data.session;}catch(e){cloudState='Cloud unavailable';render();return;}if(session){try{await loadAccess();if(access&&access.role!=='client')await loadCloud(false);}catch(e){cloudState='Cloud unavailable';}}render();void refreshFX();setInterval(()=>refreshFX(),3600000);window.addEventListener('focus',()=>refreshFX());window.addEventListener('beforeunload',e=>{if(cloudPending||cloudBusy){e.preventDefault();e.returnValue=''}});}
bootStudio();
